def compute(vars):
    adjustment_606 = vars["v1"]
    adjustment_financial_instruments = vars["v2"]
    adjustment_income_taxes = vars["v3"]
    adjusted_retained_earnings = vars["v4"]

    net_adjustments = (
        adjustment_606
        + adjustment_financial_instruments
        + adjustment_income_taxes
    )

    if adjusted_retained_earnings == 0:
        return None

    value = net_adjustments / adjusted_retained_earnings * 100

    return {
        "value": value,
        "trace": {
            "net_adjustments": net_adjustments,
            "adjusted_retained_earnings": adjusted_retained_earnings,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }

def compute(vars):
